with incoming(lemma, kind, sense_id, ordinal, pos, gender, text, example, example_translation) as (values ('flytte ind', 'phrase', '66d96bb8-b598-53bf-b77c-2fffe69092c2', 1, 'verb', null, 'to move in (to a new home)', 'De flyttede ind i lejligheden i går.', 'They moved into the apartment yesterday.'), ('rette sig', 'phrase', 'be1f4f58-3af0-5846-981f-935527991361', 1, 'verb', null, 'to correct oneself', 'Jeg sagde forkert, men jeg rettede mig hurtigt.', 'I said the wrong thing, but I quickly corrected myself.'), ('køre over for rødt', 'phrase', '14dd8ebf-3316-5363-99a6-19ae1ce1f8d6', 1, 'verb', null, 'to run a red light', 'Han kørte over for rødt i morges.', 'He ran a red light this morning.'), ('hænge sig', 'phrase', '36dcc5ea-c21a-55ef-9ee7-4e889898815b', 1, 'verb', null, 'to hang oneself', 'Han hængte sig i garagen.', 'He hanged himself in the garage.'), ('hænge sig', 'phrase', '3a257c39-349c-5da3-a138-e78ebfe6cf81', 2, 'verb', null, 'to get hung up (on something)', 'Hun hænger sig altid i små detaljer.', 'She always gets hung up on small details.'), ('kigge sig omkring', 'phrase', '0c908b2a-2a8c-5691-8e5f-2b9e2b8278f0', 1, 'verb', null, 'to look around', 'Hun kigger sig omkring i det nye hus.', 'She looks around the new house.'), ('med hensyn til', 'phrase', 'b65d91cc-1e39-5941-940e-4edc97852fbb', 1, 'preposition', null, 'regarding', 'Med hensyn til maden er jeg meget tilfreds.', 'As for the food, I am very satisfied.'), ('varme sig', 'phrase', '2635c1ed-5b36-503c-8933-9d6d3403a260', 1, 'verb', null, 'to warm oneself', 'Jeg varmer mig foran pejsen.', 'I warm myself in front of the fireplace.'), ('fokusere på', 'phrase', '3baefca8-b345-5f6d-ba67-c47c9c226784', 1, 'verb', null, 'to focus (on something)', 'Vi fokuserer på de vigtigste opgaver i dag.', 'We focus on the most important tasks today.'), ('beskæftige sig med', 'phrase', '89abfd38-77c4-55c9-bb0e-7fd9f3bc3263', 1, 'verb', null, 'to occupy oneself with', 'Jeg beskæftiger mig med gamle bøger i min fritid.', 'In my spare time I occupy myself with old books.'), ('stamme fra', 'phrase', 'f312b1cc-5a70-5981-a219-24531485b358', 1, 'verb', null, 'to originate (from)', 'Mine bedsteforældre stammer fra Polen.', 'My grandparents come from Poland.'), ('teste for', 'phrase', '4ca18282-3e73-5eec-b043-cbaf4a0b02bd', 1, 'verb', null, 'to test for (something)', 'Lægen tester for bakterier i prøven.', 'The doctor tests for bacteria in the sample.'), ('bøje sig', 'phrase', 'e16dc1f6-ba63-5971-9db4-8f24edce9b05', 1, 'verb', null, 'to bend down', 'Han bøjede sig for at tage nøglen op.', 'He bent down to pick up the key.'), ('forene sig', 'phrase', 'e6a168eb-d106-5586-bfc9-8384870fa25e', 1, 'verb', null, 'to unite', 'De to grupper forenede sig for at blive stærkere.', 'The two groups united to become stronger.'), ('komme i gang', 'phrase', '2eabe208-da37-5fb9-9f46-f711640fd138', 1, 'verb', null, 'to get started', 'Vi kom i gang med projektet i går.', 'We got started on the project yesterday.'), ('være sig selv', 'phrase', '8abe15da-47ce-5453-bed2-95b8947d0851', 1, 'verb', null, 'to be oneself', 'Du skal bare være dig selv til festen.', 'You just have to be yourself at the party.'), ('komme sammen', 'phrase', 'bea1a2bd-3df2-5304-83ac-4ef20201de87', 1, 'verb', null, 'to socialise (spend time together)', 'Vi kommer sammen med naboerne hver fredag.', 'We get together with the neighbors every Friday.'), ('arbejde over', 'phrase', '637749d4-bef0-56db-9187-350b0fa23dae', 1, 'verb', null, 'to work overtime', 'Jeg arbejder over hver dag i denne uge.', 'I''m working overtime every day this week.'), ('tage plads', 'phrase', 'f110c2a3-bd19-541a-9a37-532646069448', 1, 'verb', null, 'to take a seat', 'De tog plads ved bordet og ventede på maden.', 'They took a seat at the table and waited for the food.'), ('høre op', 'phrase', '6fbc7261-f8fd-52af-b12b-bd9d1602920b', 1, 'verb', null, 'to stop (doing something)', 'Han hørte op med at ryge sidste år.', 'He quit smoking last year.'), ('høre op', 'phrase', 'c56a962d-cfa2-5d3a-a772-90e6b2fc9bc7', 2, 'verb', null, 'to cease (of sound, noise)', 'Regnen hørte op i morges.', 'The rain stopped this morning.'), ('trække på', 'phrase', 'a69924e9-e255-572c-928a-21af76db4000', 1, 'verb', null, 'to draw on (experience)', 'Hun trækker på sin erfaring fra tidligere job.', 'She draws on her experience from previous jobs.'), ('sikre sig', 'phrase', '53de5466-8d0d-5679-8a22-62cc663dd95e', 1, 'verb', null, 'to secure (something for oneself)', 'Hun sikrede sig en god plads til koncerten.', 'She secured a good seat for the concert.'), ('hjælpe til', 'phrase', 'c7e41d73-cd7b-548a-91b1-b4c118d76123', 1, 'verb', null, 'to help out (joining in)', 'Børnene hjælper til i haven om søndagen.', 'The children help out in the garden on Sundays.'), ('spørge sig selv', 'phrase', 'e9261a22-9233-5ca3-bd8b-964b1bd2f2f3', 1, 'verb', null, 'to ask oneself (to wonder)', 'Jeg spørger mig selv, om det er en god idé.', 'I wonder if this is a good idea.'), ('længes efter', 'phrase', 'e25c1a50-c2c2-53c0-b92f-32cd27f0aaed', 1, 'verb', null, 'to long for', 'Hun længes efter sin familie i hjemlandet.', 'She longs for her family in her home country.'), ('tage imod', 'phrase', '8f56dbd3-e9c2-5874-a6db-daaf5c20ede6', 1, 'verb', null, 'to receive (guests, gifts, advice)', 'Hun tager imod gæster hele dagen.', 'She receives guests throughout the day.'), ('bestå i at', 'phrase', 'd2399265-37d4-5f98-9e40-59d55808df1a', 1, 'verb', null, 'to consist in doing', 'Opgaven består i at finde fejlene i teksten.', 'The task consists in finding the errors in the text.'), ('huske på at', 'phrase', '837e5c50-bcf7-5b44-a199-bc239bcf993f', 1, 'verb', null, 'to remember to (do something)', 'Husk på at låse døren når du går.', 'Remember to lock the door when you leave.'), ('tale i telefon', 'phrase', '7a5faba7-87f9-5c48-9314-80fb7963c8ab', 1, 'verb', null, 'to talk on the phone', 'Jeg taler i telefon med min mor hver aften.', 'I talk to my mother on the phone every evening.'), ('spise til aften', 'phrase', 'abf2f0af-a29d-50e9-a8e0-9d1a2383f39e', 1, 'verb', null, 'to have dinner', 'Vi spiser til aften klokken seks.', 'We have dinner at six o''clock.'), ('have adgang til', 'phrase', '0557d320-45ee-511f-befe-ebd4d0306f27', 1, 'verb', null, 'to have access to', 'Alle studerende har adgang til bibliotekets online databaser.', 'All students have access to the library''s online databases.'), ('kigge forbi', 'phrase', '7b07b811-ab61-5c39-89b5-d713d567b541', 1, 'verb', null, 'to drop by', 'Jeg kigger forbi i morgen eftermiddag.', 'I''ll stop by tomorrow afternoon.'), ('udtrykke sig', 'phrase', '7be004aa-7f28-50cc-b60a-1a4cfe67402b', 1, 'verb', null, 'to express oneself', 'Han udtrykker sig altid meget klart.', 'He always expresses himself very clearly.'), ('brænde ned', 'phrase', 'e8442488-a96e-515f-8b6b-0a018ab266c5', 1, 'verb', null, 'to burn down', 'Det gamle hus brændte ned i nat.', 'The old house burned down last night.'), ('høre radio', 'phrase', 'bcc780d0-7b44-5718-8a32-e5e5271b2ff9', 1, 'verb', null, 'to listen to the radio', 'Jeg hører radio hver morgen.', 'I listen to the radio every morning.'), ('røre i', 'phrase', 'bdf22fc4-b0ef-564f-9da7-ebdc10c71557', 1, 'verb', null, 'to stir (in a liquid)', 'Hun rører i suppen med en ske.', 'She stirs the soup with a spoon.'), ('insistere på', 'phrase', 'd2321ba1-f985-55c2-84c8-ea87db698dc8', 1, 'verb', null, 'to insist on', 'Hun insisterede på at betale for maden.', 'She insisted on paying for the food.'), ('styrte ned', 'phrase', '07012a7c-1de9-5fe8-beb7-d2a1928909bf', 1, 'verb', null, 'to collapse (plans, system)', 'Hele systemet styrtede ned.', 'The whole system crashed.'), ('lægge på', 'phrase', '0bd3bf5b-9c4e-5453-8630-46fa0e34011b', 1, 'verb', null, 'to hang up (the phone)', 'Hun lagde på uden at sige farvel.', 'She hung up without saying goodbye.'), ('gå foran', 'phrase', 'b6732ccc-82b6-5224-85ca-2918578c1e79', 1, 'verb', null, 'to walk in front', 'Hun gik foran os hele vejen til stationen.', 'She walked in front of us all the way to the station.'), ('gå foran', 'phrase', '4e4e363b-a1f9-599c-b095-ec3a5e28357e', 2, 'verb', null, 'to lead by example', 'Lederen bør gå foran og vise, hvordan man gør.', 'The leader should lead by example and show how to do it.'), ('stemme for', 'phrase', '433029a1-4992-5177-b5d4-59985fce3563', 1, 'verb', null, 'to vote for', 'Mange danskere stemmer for den nye lov.', 'Many Danes are voting in favour of the new law.'), ('sige tak', 'phrase', 'b2e837c0-0752-5bff-a1cb-c04d6c1e4e94', 1, 'verb', null, 'to say thank you', 'Hun sagde tak for gaven.', 'She said thank you for the gift.'), ('springe ud', 'phrase', '6ed218ff-afe2-5b67-b880-83887f54b271', 1, 'verb', null, 'to come out (as LGBT)', 'Hun sprang ud som homoseksuel for sine forældre.', 'She came out as gay to her parents.')),
known as (
  select incoming.* from incoming
  where exists (
    select 1 from public.word_catalog_sense existing
    where existing.lemma = incoming.lemma and existing.kind = incoming.kind
      and existing.sense_id = incoming.sense_id::uuid and existing.lang <> 'en'
  )
),
written as (
  insert into public.word_catalog_sense (lemma, kind, sense_id, ordinal, lang, text, pos, gender, example, example_translation, generator)
  select lemma, kind, sense_id::uuid, ordinal, 'en', text, pos, gender, example, example_translation, 'pipeline-phrases-0005' from known
  on conflict (lemma, kind, sense_id, lang) do update set
    text = excluded.text, example = excluded.example, example_translation = excluded.example_translation, generator = excluded.generator
  returning 1
)
select (select count(*) from incoming) as incoming, (select count(*) from known) as matched, (select count(*) from written) as written;
